fn flush(&mut self) {
        if self.spans.is_empty() {
            return;
        }
        let code = self.code;
        let indent = self.indent + self.quote * 2;
        let mut spans = std::mem::take(&mut self.spans);
        if self.quote > 0 {
            let mut prefix: Vec<Span> = Vec::with_capacity(self.quote);
            for _ in 0..self.quote {
                prefix.push(Span {
                    ink: Ink::Dim,
                    text: "│ ".into(),
                });
            }
            prefix.append(&mut spans);
            spans = prefix;
        }
        if self.heading {
            spans.insert(0, Span { ink: Ink::Dim, text: "▌ ".into() });
            self.heading = false;
        }
        self.blocks.push(Block { indent, spans, code });
    }

    #[allow(dead_code)]
    fn table(&self) -> bool {
        self.in_table
    }
}

